#[verifier::external_trait_specification]
#[verifier::external_trait_extension(ShrSpec via ShrSpecImpl)]
pub trait ExShr<Rhs = Self> {
    type ExternalTraitSpecificationFor: core::ops::Shr<Rhs>;
    type Output;

    spec fn obeys_shr_spec() -> bool;

    spec fn shr_req(self, rhs: Rhs) -> bool
        where Self: Sized;

    spec fn shr_spec(self, rhs: Rhs) -> Self::Output
        where Self: Sized;

    fn shr(self, rhs: Rhs) -> (ret: Self::Output)
        requires
            self.shr_req(rhs),
        ensures
            Self::obeys_shr_spec() ==> ret == self.shr_spec(rhs);
}
